export default async function handler(req, res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
  res.setHeader('Cache-Control', 'no-store');
  if (req.method === 'OPTIONS') { res.status(204).end(); return; }
  const allowLive = (req.headers['x-arl-live'] === '1') || (req.headers.host && req.headers.host.indexOf('localhost') === 0);
  if (allowLive) {
    try {
      const sql = (await import('mssql')).default;
      const pool = await sql.connect({
        user: process.env.MSSQL_USER || 'mcp_user',
        password: process.env.MSSQL_PASSWORD,
        server: process.env.MSSQL_SERVER || '203.202.241.211',
        port: parseInt(process.env.MSSQL_PORT || '1433', 10),
        database: process.env.MSSQL_DATABASE || 'DataMart',
        options: { encrypt: false, trustServerCertificate: true },
        requestTimeout: 5000, connectionTimeout: 3000
      });
      const [invSt, prPoGrn, prod, otif] = await Promise.all([
        pool.request().query(`SELECT TOP 10 [Business Unit] AS bu, Plant AS plant, Warehouse AS wh, SUM(ClosingStock) AS closingQty, ROUND(SUM(issueOrReceiveValue),2) AS txnValue FROM inv.tblInventoryStatement WHERE dteTransactionDate >= DATEADD(day,-30,GETDATE()) GROUP BY [Business Unit], Plant, Warehouse ORDER BY SUM(issueOrReceiveValue) DESC`),
        pool.request().query(`SELECT TOP 10 strBusinessUnitName AS bu, COUNT(DISTINCT intPurchaseRequestId) AS prCount, ROUND(SUM(prQTY),0) AS prQty, ROUND(SUM(poQTY),0) AS poQty, ROUND(SUM(grnQTY),0) AS grnQty FROM pro.tblPRtoBP WHERE dtePRDate >= DATEADD(day,-60,GETDATE()) GROUP BY strBusinessUnitName ORDER BY SUM(prQTY) DESC`),
        pool.request().query(`SELECT TOP 10 strBusinessUnitName AS bu, COUNT(DISTINCT strProductionCode) AS batches, ROUND(SUM(numQuantity),0) AS producedQty, ROUND(SUM(GRNValue),2) AS grnValue FROM mes.tblProductionDetails WHERE dteProductionDate >= DATEADD(day,-60,GETDATE()) GROUP BY strBusinessUnitName ORDER BY SUM(numQuantity) DESC`),
        pool.request().query(`SELECT TOP 4000 strPurchaseOrderNo AS po, strBusinessPartnerName AS supplier, strBusinessUnitName AS sbu, ISNULL(strPlantName,'') AS plant, ISNULL(strWarehouseName,'') AS wh, CONVERT(varchar(10), dtePurchaseOrderDate, 23) AS poDate, CONVERT(varchar(10), dteDueDate, 23) AS dueDate, CONVERT(varchar(10), dteMrrDate, 23) AS mrrDate, ROUND(poQTY,2) AS poQty, ROUND(grnQTY,2) AS grnQty, ROUND(ISNULL(numTotalPOAmount,0),2) AS poAmount FROM pro.tblPRtoBP WHERE dtePurchaseOrderDate >= DATEADD(day,-90,GETDATE()) AND strPurchaseOrderNo IS NOT NULL AND strBusinessPartnerName IS NOT NULL AND strBusinessUnitName NOT LIKE '%Demo%' ORDER BY dtePurchaseOrderDate DESC`)
      ]);
      await pool.close();
      res.status(200).json({ generatedAt: new Date().toISOString(), inventoryStatement: invSt.recordset, prPoGrn: prPoGrn.recordset, production: prod.recordset, otif: otif.recordset, source: 'live' });
      return;
    } catch (e) { console.error('datamart live error:', e.message); }
  }
  res.status(200).json({ generatedAt: new Date().toISOString(), inventoryStatement: INV_STATEMENT, prPoGrn: PR_PO_GRN, production: PRODUCTION, otif: OTIF_ROWS, source: 'snapshot' });
}
